const body = $json.body || {};
const query = $json.query || {};
const staticData = $getWorkflowStaticData('global');
const now = new Date();

const reset = body.reset_monitor === true || body.reset_monitor === 'true' || query.reset_monitor === 'true';
if (reset) {
  delete staticData.startedAt;
  delete staticData.endsAt;
  staticData.alerted = {};
}

if (!staticData.startedAt) {
  staticData.startedAt = now.toISOString();
  staticData.endsAt = new Date(now.getTime() + 48 * 60 * 60 * 1000).toISOString();
  staticData.alerted = staticData.alerted || {};
}

const startedAt = staticData.startedAt;
const endsAt = staticData.endsAt;
const expired = now.getTime() > new Date(endsAt).getTime();
const isWebhook = Boolean($json.body || $json.query || $json.headers);
const forceTest = body.send_test === true || body.send_test === 'true' || query.send_test === 'true';

return [{ json: {
  source: isWebhook ? 'manual' : 'schedule',
  started_at: startedAt,
  ends_at: endsAt,
  expired,
  force_test: forceTest,
  alert_phone_input: '21999910781',
  alert_phone_wa: '5521999910781',
  checked_at: now.toISOString(),
} }];

