={{ "SET search_path TO sales_prod, public, extensions;\n" + ((() => {
  const start = String($json.started_at || new Date(Date.now() - 48 * 60 * 60 * 1000).toISOString()).replace(/'/g, "''");
  if ($json.expired === true || String($json.expired) === 'true') {
    return "SELECT now()::text AS checked_at, '[]'::jsonb AS rows";
  }
  return `WITH candidate_rows AS (
  SELECT
    id::text,
    status::text,
    cris_state::text,
    quicklink_estado::text,
    quicklink_observacion::text,
    COALESCE(last_error, '')::text AS last_error,
    created_at::text,
    sent_at::text,
    CASE
      WHEN status IN ('FAILED','RETRYING') THEN 'queue_problem'
      WHEN cris_state IN ('LOST','CONTACTAR') THEN 'v98_final_state'
      ELSE 'other'
    END AS alert_kind
  FROM quicklink_report_queue
  WHERE created_at >= '${start}'::timestamptz
    AND status <> 'SKIPPED'
    AND COALESCE(last_error, '') NOT LIKE 'skipped%'
    AND (
      cris_state IN ('LOST','CONTACTAR')
      OR status IN ('FAILED','RETRYING')
    )
  ORDER BY created_at DESC, id DESC
  LIMIT 50
)
SELECT
  now()::text AS checked_at,
  COALESCE(jsonb_agg(to_jsonb(candidate_rows) ORDER BY created_at DESC), '[]'::jsonb) AS rows
FROM candidate_rows;`;
})()) }}

