const setup = $('Code - Monitor Setup').first().json || {};
const row = $input.first()?.json || {};
const rows = Array.isArray(row.rows) ? row.rows : [];
const staticData = $getWorkflowStaticData('global');
staticData.alerted = staticData.alerted || {};

const now = new Date().toISOString();
const to = setup.alert_phone_wa || '5521999910781';

function textPayload(body) {
  return {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to,
    type: 'text',
    text: { preview_url: false, body },
  };
}

function clip(value, max = 180) {
  const s = String(value || '').trim();
  return s.length > max ? s.slice(0, max - 3) + '...' : (s || '-');
}

const alerts = [];

if (setup.force_test) {
  alerts.push({
    kind: 'monitor_test',
    dedupe_key: '',
    message: [
      'CRIS V98 monitor activo por 48h.',
      'Destino: 21999910781 / WA 5521999910781.',
      'Avisare cuando aparezca un caso real LOST/CONTACTAR o una falla de cola QuickLink.',
      'Inicio: ' + setup.started_at,
      'Expira: ' + setup.ends_at,
    ].join('\n'),
  });
}

if (setup.expired === true || String(setup.expired) === 'true') {
  const key = 'monitor:expired';
  if (!staticData.alerted[key]) {
    alerts.push({
      kind: 'monitor_expired',
      dedupe_key: key,
      message: [
        'CRIS V98 monitor 48h expiro.',
        'No se enviaran mas alertas automaticas desde esta ventana.',
        'Inicio: ' + setup.started_at,
        'Expira: ' + setup.ends_at,
      ].join('\n'),
    });
  }
} else {
  for (const r of rows) {
    const key = `queue:${r.id}:${r.status}`;
    if (staticData.alerted[key]) continue;

    const validated = r.status === 'SENT' && (r.cris_state === 'LOST' || r.cris_state === 'CONTACTAR');
    const header = validated
      ? 'CRIS V98 PRODUCCION VALIDADA'
      : (r.alert_kind === 'queue_problem' ? 'CRIS QuickLink cola requiere revision' : 'CRIS V98 caso real detectado');

    const lines = [
      header,
      'Status cola: ' + clip(r.status, 40),
      'Estado CRIS: ' + clip(r.cris_state, 40),
      'QuickLink: ' + clip(r.quicklink_estado, 80),
      'Observacion: ' + clip(r.quicklink_observacion, 140),
      'Queue ID: ' + clip(r.id, 80),
      'Creado: ' + clip(r.created_at, 80),
      'Enviado: ' + clip(r.sent_at, 80),
    ];
    if (r.last_error) lines.push('Error: ' + clip(r.last_error, 180));
    if (validated) lines.push('Resultado: primer caso real llego a SENT.');

    alerts.push({
      kind: r.alert_kind,
      queue_id: r.id,
      queue_status: r.status,
      dedupe_key: key,
      message: lines.join('\n'),
    });
  }
}

if (!alerts.length) {
  return [{ json: {
    send_alert: false,
    status: setup.expired ? 'monitor_expired_no_new_alerts' : 'no_new_alerts',
    rows_seen: rows.length,
    started_at: setup.started_at,
    ends_at: setup.ends_at,
    checked_at: now,
  } }];
}

return alerts.map(alert => ({ json: {
  send_alert: true,
  alert_phone_wa: to,
  checked_at: now,
  started_at: setup.started_at,
  ends_at: setup.ends_at,
  ...alert,
  meta_payload: textPayload(alert.message),
} }));

const staticData = $getWorkflowStaticData('global');
staticData.alerted = staticData.alerted || {};
const sourceAlerts = $('Code - Build Alerts').all().map(i => i.json || {}).filter(i => i.send_alert);
const httpItems = $input.all();
const results = httpItems.map((item, index) => {
  const alert = sourceAlerts[index] || {};
  const http = item.json || {};
  const statusCode = Number(http.statusCode || http.status || 0);
  const ok = statusCode >= 200 && statusCode < 300;
  if (ok && alert.dedupe_key) {
    staticData.alerted[alert.dedupe_key] = new Date().toISOString();
  }
  return {
    kind: alert.kind || 'unknown',
    queue_id: alert.queue_id || null,
    queue_status: alert.queue_status || null,
    dedupe_key: alert.dedupe_key || null,
    whatsapp_status_code: statusCode || null,
    sent_ok: ok,
    meta_message_id: http.body?.messages?.[0]?.id || http.messages?.[0]?.id || null,
    meta_error: http.body?.error || http.error || null,
  };
});
return [{ json: {
  status: results.every(r => r.sent_ok) ? 'alerts_sent' : 'alerts_partial_or_failed',
  sent_count: results.filter(r => r.sent_ok).length,
  failed_count: results.filter(r => !r.sent_ok).length,
  results,
} }];
